#!/usr/bin/env bash
# Bundle item 166_foreign_sdg31_pre_video (thread "Videos: Foreign Affairs committee meetings", generated 22 Nov 2569)
# Applies only the videos listed below (already-live ones untouched); new in this item: SDG subcommittee 31 before-meeting video (25 Nov 2569, notice ว1069)
# Puts the SDG subcommittee meeting 31 before-meeting video on parliamentx.com/foreign/2569/sub-sdg.html.
# 1080x1920, Thai voice + English subtitles burned in (one version), kind="pre"/"post". No private names, no company names,
# no MP named as a bill's proposer (checked in each video's legal pack).
# Generated by a filtered copy of committees/foreign/tools/gen_bundle_item_videos.py (only sdg 31; run after item 163, which adds the meeting 31 row).
# Surgical: copies mp4/vtt/poster files, replaces only the "media" field of those meetings in the DATA line of
# foreign/2569/index.html + sub-<key>.html and in meetings.json + sub-<key>.json, fills the CAPS caption tracks,
# makes the video share pages (video_share.py, CARD_BIG=1), re-applies no_video_dl to s/, then refreshes the home page
# newest-4 video list and the Foreign Affairs 2569 snapshot "v".
# Idempotent; no git, no network. Needs $HUB $BUILD.
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
# One self-contained file: mp4 / Thai vtt / poster are embedded below as base64 tar.gz (sha256 bbbc5d605091a50ba3e33b45152fec85fe03aa5104d0a13af1bf1189947dd728); nothing is read from the shared media folder.
SRC=/tmp/166_foreign_sdg31_pre_video_payload
rm -rf "$SRC"; mkdir -p "$SRC"
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d > "$SRC/p.tgz"
echo "bbbc5d605091a50ba3e33b45152fec85fe03aa5104d0a13af1bf1189947dd728  $SRC/p.tgz" | sha256sum -c --quiet - || { echo "166_foreign_sdg31_pre_video: embedded payload damaged" >&2; exit 1; }
tar -xzf "$SRC/p.tgz" -C "$SRC"
L="$HUB/foreign/2569"
test -f "$L/index.html" -a -f "$L/sub-sdg.html" -a -f "$L/sub-sdg.json" -a -f "$L/meetings.json" || { echo "166_foreign_sdg31_pre_video: $L pages missing (needs the Foreign Affairs committee item 96_transport_foreign)" >&2; exit 1; }
test -f "$HUB/index.html" || { echo "166_foreign_sdg31_pre_video: hub index.html missing" >&2; exit 1; }
# files must be whole: 1080x1920 video of the listed length, WEBVTT captions
for v in sub-sdg-v31pre:150; do f=${v%%:*}; want=${v##*:}
  test -s "$SRC/$f.mp4" -a -s "$SRC/$f.th.vtt" || { echo "166_foreign_sdg31_pre_video: $SRC/$f missing" >&2; exit 1; }
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$SRC/$f.mp4")
  python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<1.5 else 1)" || { echo "166_foreign_sdg31_pre_video: $f length $dur, expected ~$want s" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$SRC/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "166_foreign_sdg31_pre_video: $f size $wh" >&2; exit 1; }
  head -1 "$SRC/$f.th.vtt" | grep -q '^WEBVTT' || { echo "166_foreign_sdg31_pre_video: $f vtt header" >&2; exit 1; }
done
mkdir -p "$L/media" "$L/img"
for f in sub-sdg-v31pre.mp4 sub-sdg-v31pre.th.vtt; do cmp -s "$SRC/$f" "$L/media/$f" || cp -f "$SRC/$f" "$L/media/$f"; cmp -s "$SRC/$f" "$L/media/$f"; done
for f in poster-sub-sdg-31pre.jpg; do cmp -s "$SRC/$f" "$L/img/$f" || cp -f "$SRC/$f" "$L/img/$f"; cmp -s "$SRC/$f" "$L/img/$f"; done
python3 - "$HUB" <<'PY'
import json, os, sys
HUB = sys.argv[1]; L = os.path.join(HUB, 'foreign', '2569')
D = json.loads(r"""{
"MEDIA": {
"sub-sdg.html": {
"31|2026-11-25": {
"video": {
"src": "media/sub-sdg-v31pre.mp4",
"poster": "img/poster-sub-sdg-31pre.jpg",
"vtt": "media/sub-sdg-v31pre.th.vtt",
"kind": "pre",
"label": "วิดีโอก่อนการประชุม",
"dur": "2:30",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "sdg-31p"
},
"videos": [
{
"src": "media/sub-sdg-v31pre.mp4",
"poster": "img/poster-sub-sdg-31pre.jpg",
"vtt": "media/sub-sdg-v31pre.th.vtt",
"kind": "pre",
"label": "วิดีโอก่อนการประชุม",
"dur": "2:30",
"cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
"ck": "sdg-31p"
}
]
}
}
},
"CAPK": {
"sub-sdg.html": {
"sdg-31p": "media/sub-sdg-v31pre.th.vtt"
}
},
"JSONS": {
"sub-sdg.html": "sub-sdg.json"
}
}""")
MEDIA, CAPK, JSONS = D['MEDIA'], D['CAPK'], D['JSONS']
CMP = dict(ensure_ascii=False, separators=(',', ':'))
ser = lambda a: json.dumps(a, **CMP).replace('</', '<\\/')
changed = []

def put(path, text):
    old = open(path, encoding='utf-8').read()
    if old != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.relpath(path, HUB))

def sized(md):
    md = json.loads(json.dumps(md))
    for v in [md['video']] + md['videos']:
        v['size'] = os.path.getsize(os.path.join(L, v['src']))
    return md

def jline(lines, prefix, dump):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f'{prefix} line not found once'
    line = lines[idx[0]]; body = line[len(prefix):]; tail = body[len(body.rstrip().rstrip(';')):]
    val = json.loads(body[:len(body) - len(tail)])
    assert prefix + dump(val) + tail == line, f'{prefix} line does not round-trip; not touching it'
    return idx[0], val, tail

for page, want in MEDIA.items():
    p = os.path.join(L, page); lines = open(p, encoding='utf-8').read().split('\n')
    # 1) DATA line: replace only "media" of the meetings that have a video
    i, arr, tail = jline(lines, 'const DATA=', ser)
    keys = {f"{m['n']}|{m['date']}": m for m in arr}
    for k, md in want.items():
        assert k in keys, f'{page}: meeting {k} not on the page'
        keys[k]['media'] = sized(md)
    lines[i] = 'const DATA=' + ser(arr) + tail
    # 2) CAPS line: Thai caption track per video (kept off by default on the page, cc says English is burned in)
    i, caps, tail = jline(lines, 'const CAPS=', lambda a: json.dumps(a, ensure_ascii=False))
    for ck, vtt in CAPK[page].items():
        caps[ck] = open(os.path.join(L, vtt), encoding='utf-8').read()
    lines[i] = 'const CAPS=' + json.dumps(caps, ensure_ascii=False) + tail
    put(p, '\n'.join(lines))
    # 3) the page's meeting list json (indent=1, no final newline, as csite writes it)
    p = os.path.join(L, JSONS[page]); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f'{JSONS[page]} does not round-trip; not touching it'
    mk = {f"{m['n']}|{m['date']}": m for m in ms}
    for k, md in want.items():
        assert k in mk, f'{JSONS[page]}: meeting {k} missing'
        mk[k]['media'] = sized(md)
    put(p, json.dumps(ms, ensure_ascii=False, indent=1))

# 4) home page: newest-4 video list (same rules as archive/hub/home.py) + Foreign Affairs 2569 snapshot "v" counts
ms = json.load(open(os.path.join(L, 'meetings.json'), encoding='utf-8'))
p = os.path.join(HUB, 'index.html'); t = open(p, encoding='utf-8').read(); dec = json.JSONDecoder()
mark = 'const HH = '
if t.count(mark) == 1:
    i = t.index(mark) + len(mark); hh, _ = dec.raw_decode(t[i:])
    old_s = ser(hh['videos'])
    assert t.count(old_s) == 1, 'home: video list text not found once'
    law = []
    for m in ms:
        for v in (m.get('media') or {}).get('videos') or []:
            law.append(dict(n=m['n'], date=m['date'], year=2569, who='กมธ.การต่างประเทศ', label=v.get('label') or 'วิดีโอสรุป',
                            dur=v.get('dur', ''), poster='foreign/2569/' + v['poster'] if v.get('poster') else '',
                            headline='' if m.get('pending') else (m.get('headline') or ''), href=f"foreign/2569/#read-{m['n']}"))
    seen = {(v['href'], v['poster']) for v in hh['videos']}
    vids = hh['videos'] + [v for v in law if (v['href'], v['poster']) not in seen]
    vids.sort(key=lambda v: v['date'], reverse=True)
    t = t.replace(old_s, ser(vids[:4]), 1)
else:
    print('166_foreign_sdg31_pre_video: home page has no HH list (skipped)')
dm = 'const DATA = '
assert t.count(dm) == 1, 'home: DATA not found once'
j = t.index(dm) + len(dm); hub, _ = dec.raw_decode(t[j:])
nv = {(m['n'], m['date']): len((m.get('media') or {}).get('videos') or []) for m in ms}
assert any(c.get('id') == 'foreign' for c in hub), 'home: Foreign Affairs committee not in DATA (needs item 96_transport_foreign)'
for c in hub:
    if c.get('id') != 'foreign':
        continue
    for y in c.get('years', []):
        if y.get('year') != 2569:
            continue
        for s in y.get('snap') or []:
            want = nv.get((s['n'], s['date']))
            if want is not None and s.get('v') != want:
                a = ser(s); s['v'] = want; b = ser(s)
                assert t.count(a) == 1, f'home: snapshot entry {s["n"]} not found once'
                t = t.replace(a, b, 1)
put(p, t)
print('166_foreign_sdg31_pre_video: changed', len(changed), 'text files:', ', '.join(changed) or 'none (already applied)')
PY

# 5) video share pages + cards (s/v-<n>[-pre].html, s/v-<key>-<n>[-pre].html, img/v/*.jpg; VSHARE map in the pages)
#    CARD_BIG=1 = the live large-text card design (item 18). video_share.py rewrites share pages without the no-download
#    layer, so no_video_dl.py goes straight after (item 21), then the whole-site check.
CARD_BIG=1 python3 "$BUILD/video_share.py" "$L" https://parliamentx.com/foreign/2569 2569
python3 "$BUILD/no_video_dl.py" "$L/s"
python3 "$BUILD/no_video_dl.py" --check "$L"
for f in v-sdg-31-pre; do test -f "$L/s/$f.html" || { echo "166_foreign_sdg31_pre_video: share page s/$f.html missing" >&2; exit 1; }; done
python3 - "$L" <<'PY'
import json, sys
L = sys.argv[1]
for page, ks in (('sub-sdg.html', ('31',)),):
    t = open(f'{L}/{page}', encoding='utf-8').read()
    vs = [l for l in t.split('\n') if l.startswith('const VSHARE=')]
    assert vs and all(f'"{k}":' in vs[0] for k in ks), f'{page}: VSHARE missing {ks}'
    assert t.count('"kind":"post"') + t.count('"kind":"pre"') >= 2 * {'sub-sdg.html': 1}[page], f'{page}: kind pre/post labels missing'
print('166_foreign_sdg31_pre_video OK')
PY

# 6) videos out of the main site (thread "Site: Move videos to a separate video site", item 90): every linked mp4 moves to the
#    video repos and links are rewritten. Idempotent; run_bundle.sh runs the same step again at the end of the bundle.
#    Push + merge the changed video repos BEFORE the main site (archive/video_repos/README.md).
VR=/mnt/project-files/archive/video_repos
if [ "${ITEM_TEST_NO_OFFLOAD:-}" = 1 ]; then echo "166_foreign_sdg31_pre_video: offload skipped (sandbox test only)"
else
  test -f $VR/ACTIVE || { echo "166_foreign_sdg31_pre_video: video repos not active yet (needs item 90 first); refusing to leave videos on the main site" >&2; exit 1; }
  grep -qxF '*.mp4' $HUB/.gitignore 2>/dev/null || { echo "166_foreign_sdg31_pre_video: $HUB/.gitignore has no *.mp4 line (needs item 90 first)" >&2; exit 1; }
  python3 "$BUILD/video_offload.py" "$HUB" --report $VR/OFFLOAD_166_foreign_sdg31_pre_video.md
  python3 /mnt/project-files/archive/check/video_host_check.py "$HUB"
  if find "$L" -name '*.mp4' | grep -q .; then echo "166_foreign_sdg31_pre_video: mp4 still on the main site after offload" >&2; exit 1; fi
fi
echo "166_foreign_sdg31_pre_video OK"
exit 0
